// Changes: Behaviour of the rules (P) editor keys – Tab only completes, it never traps focus.

import { describe, expect, it } from 'vitest'
import { rulesEditorKey, suggestionAnnouncement } from './rulesKeys'

describe('suggestionAnnouncement', () => {
  it('says how many symbols are offered (Slovak plural) and how to take one', () => {
    expect(suggestionAnnouncement(1)).toBe('1 návrh, Tab alebo Enter doplní, šípky vyberajú.')
    expect(suggestionAnnouncement(3)).toBe('3 návrhy, Tab alebo Enter doplní, šípky vyberajú.')
    expect(suggestionAnnouncement(8)).toBe('8 návrhov, Tab alebo Enter doplní, šípky vyberajú.')
  })

  it('is silent when nothing is offered', () => {
    expect(suggestionAnnouncement(0)).toBe('')
  })
})

const key = (key: string, mods: Partial<{ shiftKey: boolean; ctrlKey: boolean; altKey: boolean; metaKey: boolean; isComposing: boolean; keyCode: number }> = {}) => ({
  key,
  shiftKey: false,
  ctrlKey: false,
  altKey: false,
  metaKey: false,
  isComposing: false,
  keyCode: 0,
  ...mods,
})
const closed = { popupOpen: false, beforeCaret: 'E -> T ', hasSelection: false, dismissed: false }
const open = { ...closed, popupOpen: true }

describe('rulesEditorKey', () => {
  it('lets Tab and Shift+Tab move focus out of the editor in the middle of a rule', () => {
    expect(rulesEditorKey(key('Tab'), closed)).toBeNull()
    expect(rulesEditorKey(key('Tab', { shiftKey: true }), closed)).toBeNull()
  })

  it('opens the completion (ε first) with Tab on an empty right-hand side', () => {
    expect(rulesEditorKey(key('Tab'), { ...closed, beforeCaret: 'E -> ' })).toBe('open')
    expect(rulesEditorKey(key('Tab'), { ...closed, beforeCaret: 'E → T | ' })).toBe('open')
    expect(rulesEditorKey(key('Tab'), { ...closed, beforeCaret: 'E ::=' })).toBe('open')
  })

  it('moves focus with Tab after the list was dismissed there, inside quotes, with a selection or with Shift', () => {
    expect(rulesEditorKey(key('Tab'), { ...closed, beforeCaret: 'E -> ', dismissed: true })).toBeNull()
    expect(rulesEditorKey(key('Tab'), { ...closed, beforeCaret: "E -> '|" })).toBeNull()
    expect(rulesEditorKey(key('Tab'), { ...closed, beforeCaret: 'E -> ', hasSelection: true })).toBeNull()
    expect(rulesEditorKey(key('Tab', { shiftKey: true }), { ...closed, beforeCaret: 'E -> ' })).toBeNull()
  })

  it('drives an open list: arrows move, Tab and Enter accept, Esc closes', () => {
    expect(rulesEditorKey(key('ArrowDown'), open)).toBe('next')
    expect(rulesEditorKey(key('ArrowUp'), open)).toBe('prev')
    expect(rulesEditorKey(key('Tab'), open)).toBe('accept')
    expect(rulesEditorKey(key('Enter', { keyCode: 13 }), open)).toBe('accept')
    expect(rulesEditorKey(key('Escape'), open)).toBe('close')
  })

  it('never takes Shift+Tab, even with the list open (focus leaves, the list closes on blur)', () => {
    expect(rulesEditorKey(key('Tab', { shiftKey: true }), open)).toBeNull()
  })

  it('leaves the Enter that confirms an IME composition to the IME', () => {
    expect(rulesEditorKey(key('Enter', { isComposing: true, keyCode: 13 }), open)).toBeNull()
    expect(rulesEditorKey(key('Enter', { keyCode: 229 }), open)).toBeNull()
    expect(rulesEditorKey(key('ArrowDown', { isComposing: true }), open)).toBeNull()
  })

  it('leaves arrows, Enter and Esc alone when the list is closed', () => {
    expect(rulesEditorKey(key('ArrowDown'), closed)).toBeNull()
    expect(rulesEditorKey(key('Enter', { keyCode: 13 }), closed)).toBeNull()
    expect(rulesEditorKey(key('Escape'), closed)).toBeNull()
  })

  it('lists every symbol with Ctrl+Space', () => {
    expect(rulesEditorKey(key(' ', { ctrlKey: true }), closed)).toBe('showAll')
  })
})
